"""Fetch every page of GET /orders into /tmp/recon/raw. Only GETs, plus POST /token for auth."""
import json
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime

BASE = "http://localhost:8080"
RAW = "/tmp/recon/raw"
LOG = "/tmp/recon/fetch.log"

token = None


def log(msg):
    line = f"{datetime.now(timezone.utc).strftime('%H:%M:%S.%f')[:-3]} {msg}"
    print(line, flush=True)
    with open(LOG, "a") as f:
        f.write(line + "\n")


def send(method, path, auth):
    headers = {"Authorization": f"Bearer {token}"} if auth else {}
    req = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, r.headers, r.read()
    except urllib.error.HTTPError as e:
        return e.code, e.headers, e.read()


def new_token():
    global token
    status, _, body = send("POST", "/token", auth=False)
    if status != 200:
        raise RuntimeError(f"token request returned {status}: {body[:200]!r}")
    token = json.loads(body)["token"]
    log("obtained a new token")


def parse_wait(headers, body):
    """Seconds the service asked us to wait, or None if it did not say."""
    ra = headers.get("Retry-After")
    if ra is not None:
        try:
            return float(ra)
        except ValueError:
            return max(0.0, (parsedate_to_datetime(ra) - datetime.now(timezone.utc)).total_seconds())
    try:
        data = json.loads(body)
    except ValueError:
        data = None
    if isinstance(data, dict):
        for key, value in data.items():
            if ("retry" in key.lower() or "wait" in key.lower()) and isinstance(value, (int, float)):
                return float(value)
    return None


def get_json(path, auth=True):
    """GET path until it succeeds. Returns the parsed body, or None for a 404 on a customer lookup."""
    if auth and token is None:
        new_token()
    for attempt in range(1, 61):
        try:
            status, headers, body = send("GET", path, auth)
        except OSError as e:  # URLError and timeouts are OSError subclasses
            log(f"{path}: transport error ({e}); retrying in 2s")
            time.sleep(2)
            continue
        if status == 200:
            return json.loads(body)
        text = body[:300].decode("utf-8", "replace")
        log(f"{path}: HTTP {status} (attempt {attempt}) Retry-After={headers.get('Retry-After')} body={text!r}")
        if status == 404 and path.startswith("/customers/"):
            return None
        if status in (401, 403):
            new_token()
        elif status in (429, 503):
            wait = parse_wait(headers, body)
            if wait is None:
                raise RuntimeError(f"{path}: HTTP {status} but no wait time was given: {text!r}")
            log(f"honouring service wait of {wait}s (+0.5s margin)")
            time.sleep(wait + 0.5)
        elif status >= 500:
            time.sleep(2)
        else:
            raise RuntimeError(f"{path}: unexpected HTTP {status}: {text!r}")
    raise RuntimeError(f"{path}: still failing after 60 attempts")


def fetch_orders():
    total_pages = None
    page = 1
    while True:
        body = get_json(f"/orders?page={page}")
        if body["page"] != page:
            raise RuntimeError(f"asked for page {page}, got page {body['page']}")
        if total_pages is None:
            total_pages = body["total_pages"]
        elif body["total_pages"] != total_pages:
            raise RuntimeError(f"total_pages changed from {total_pages} to {body['total_pages']} at page {page}")
        with open(f"{RAW}/page-{page:03d}.json", "w") as f:
            json.dump(body, f)
        log(f"page {page}/{total_pages}: {len(body['items'])} items, next={body['next']!r}")
        expected_next = f"/orders?page={page + 1}" if page < total_pages else None
        if body["next"] != expected_next:
            raise RuntimeError(f"page {page}: next={body['next']!r}, expected {expected_next!r}")
        if page == total_pages:
            return total_pages
        page += 1


if __name__ == "__main__":
    open(LOG, "w").close()  # fresh log for this run
    pages = fetch_orders()
    log(f"done: {pages} pages saved to {RAW}")

